","class WellService {
 constructor() {
 this.tableName = "x_1842888_drilling_well";
 }

 async getWells() {
 try {
 const response = await fetch(`/api/now/table/${this.tableName}?sysparm_display_value=all&sysparm_limit=50`, {
 method: "GET",
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 },
 });

 if (!response.ok) {
 throw new Error(`HTTP error! status: ${response.status}`);
 }

 const data = await response.json();
 return { data };
 } catch (error) {
 console.error('Error fetching wells:', error);
 throw error;
 }
 }

 async getWell(sysId) {
 try {
 const response = await fetch(`/api/now/table/${this.tableName}/${sysId}?sysparm_display_value=all`, {
 method: "GET",
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 },
 });

 if (!response.ok) {
 throw new Error(`HTTP error! status: ${response.status}`);
 }

 const data = await response.json();
 return { data };
 } catch (error) {
 console.error('Error fetching well:', error);
 throw error;
 }
 }

 async create(data) {
 try {
 const response = await fetch(`/api/now/table/${this.tableName}`, {
 method: "POST",
 headers: {
 "Content-Type": "application/json",
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 },
 body: JSON.stringify(data),
 });

 if (!response.ok) {
 throw new Error(`HTTP error! status: ${response.status}`);
 }

 const data_result = await response.json();
 return { data: data_result };
 } catch (error) {
 console.error('Error creating well:', error);
 throw error;
 }
 }

 async update(sysId, data) {
 try {
 const response = await fetch(`/api/now/table/${this.tableName}/${sysId}`, {
 method: "PATCH",
 headers: {
 "Content-Type": "application/json",
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 },
 body: JSON.stringify(data),
 });

 if (!response.ok) {
 throw new Error(`HTTP error! status: ${response.status}`);
 }

 const data_result = await response.json();
 return { data: data_result };
 } catch (error) {
 console.error('Error updating well:', error);
 throw error;
 }
 }

 async delete(sysId) {
 try {
 const response = await fetch(`/api/now/table/${this.tableName}/${sysId}`, {
 method: "DELETE",
 headers: {
 "Accept": "application/json",
 "X-UserToken": window.g_ck
 },
 });

 return response.ok;
 } catch (error) {
 console.error('Error deleting well:', error);
 throw error;
 }
 }
}

const wellService = new WellService();
export default wellService;","import React, { useState, useEffect } from 'react';
import WellService from '../services/WellService.js';

export default function WellDashboard({ selectedWell, setSelectedWell }) {
 const [wells, setWells] = useState([]);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState(null);
 const [showForm, setShowForm] = useState(false);
 const [editingWell, setEditingWell] = useState(null);

 useEffect(() => {
 loadWells();
 }, []);

 const loadWells = async () => {
 try {
 setLoading(true);
 setError(null);
 const response = await WellService.getWells();
 setWells(response.data.result || []);
 } catch (err) {
 setError(err.message);
 } finally {
 setLoading(false);
 }
 };

 const handleCreateWell = () => {
 setEditingWell(null);
 setShowForm(true);
 };

 const handleEditWell = (well) => {
 setEditingWell(well);
 setShowForm(true);
 };

 const handleCloseForm = () => {
 setShowForm(false);
 setEditingWell(null);
 };

 const getStatusBadge = (status) => {
 const statusColors = {
 planned: 'badge-secondary',
 drilling: 'badge-warning',
 completed: 'badge-info',
 producing: 'badge-success',
 suspended: 'badge-warning',
 plugged: 'badge-danger'
 };

 const statusValue = typeof status === 'object' ? status.value : status;
 const statusLabel = typeof status === 'object' ? status.display_value : status;

 return (
 <span className={`badge ${statusColors[statusValue] || 'badge-secondary'}`}>
 {statusLabel || statusValue}
 </span>
 );
 };

 const getWellTypeLabel = (wellType) => {
 return typeof wellType === 'object' ? wellType.display_value : wellType;
 };

 if (loading) {
 return (
 <div className="card">
 <div style={{ textAlign: 'center', padding: '2rem' }}>
 <div>Loading wells...</div>
 </div>
 </div>
 );
 }

 if (error) {
 return (
