 <div style={{ color: '#ef4444', textAlign: 'center', padding: '2rem' }}>
 Error: {error}
 <br />
 <button className="btn btn-primary" onClick={loadWells} style={{ marginTop: '1rem' }}>
 Retry
 </button>
 </div>
 </div>
 );
 }

 return (
 <div>
 <div className="card">
 <div className="card-header">
 <h2 className="card-title">Wells Dashboard</h2>
 <button className="btn btn-primary" onClick={handleCreateWell}>
 + Add New Well
 </button>
 </div>

 {wells.length === 0 ? (
 <div style={{ textAlign: 'center', padding: '2rem', color: '#6b7280' }}>
 No wells found. Create your first well to get started.
 </div>
 ) : (
 <div style={{ overflowX: 'auto' }}>
 <table className="table">
 <thead>
 <tr>
 <th>Well Name</th>
 <th>Well ID</th>
 <th>Location</th>
 <th>Status</th>
 <th>Type</th>
 <th>Total Depth</th>
 <th>Operator</th>
 <th>Actions</th>
 </tr>
 </thead>
 <tbody>
 {wells.map(well => {
 const wellName = typeof well.well_name === 'object' ? well.well_name.display_value : well.well_name;
 const wellId = typeof well.well_id === 'object' ? well.well_id.display_value : well.well_id;
 const location = typeof well.location === 'object' ? well.location.display_value : well.location;
 const operator = typeof well.operator === 'object' ? well.operator.display_value : well.operator;
 const totalDepth = typeof well.total_depth === 'object' ? well.total_depth.display_value : well.total_depth;
 const sysId = typeof well.sys_id === 'object' ? well.sys_id.value : well.sys_id;

 return (
 <tr 
 key={sysId}
 style={{ cursor: 'pointer' }}
 onClick={() => setSelectedWell(well)}
 className={selectedWell && 
 (typeof selectedWell.sys_id === 'object' ? selectedWell.sys_id.value : selectedWell.sys_id) === sysId 
 ? 'selected-row' : ''}
 >
 <td><strong>{wellName}</strong></td>
 <td>{wellId}</td>
 <td>{location}</td>
 <td>{getStatusBadge(well.well_status)}</td>
 <td>{getWellTypeLabel(well.well_type)}</td>
 <td>{totalDepth ? `${totalDepth} ft` : '-'}</td>
 <td>{operator}</td>
 <td>
 <button 
 className="btn btn-sm btn-secondary"
 onClick={(e) => {
 e.stopPropagation();
 handleEditWell(well);
 }}
 >
 Edit
 </button>
 </td>
 </tr>
 );
 })}
 </tbody>
 </table>
 </div>
 )}
 </div>

 {selectedWell && (
 <WellDetails 
 well={selectedWell} 
 onClose={() => setSelectedWell(null)}
 onEdit={() => handleEditWell(selectedWell)}
 />
 )}

 {showForm && (
 <WellForm 
 well={editingWell}
 onSave={loadWells}
 onClose={handleCloseForm}
 />
 )}
 </div>
 );
}

