 well_id: extractValue(well.well_id) || '',
 location: extractValue(well.location) || '',
 latitude: extractValue(well.latitude) || '',
 longitude: extractValue(well.longitude) || '',
 total_depth: extractValue(well.total_depth) || '',
 measured_depth: extractValue(well.measured_depth) || '',
 well_status: extractValue(well.well_status) || 'planned',
 well_type: extractValue(well.well_type) || 'vertical',
 operator: extractValue(well.operator) || '',
