}","class DataService {
 async makeRequest(url, options = {}) {
 try {
 const response = await fetch(url, {
 headers: {
 "Accept": "application/json",
 "Content-Type": "application/json",
 "X-UserToken": window.g_ck,
 ...options.headers
 },
 ...options
 });

 if (!response.ok) {
 throw new Error(`HTTP error! status: ${response.status}`);
 }

 const data = await response.json();
 return { data };
 } catch (error) {
 console.error('API Request Error:', error);
 throw error;
 }
 }

 async getDrillingOperations(query = '') {
 const url = `/api/now/table/x_1842888_drilling_drilling_operation?sysparm_display_value=all&sysparm_limit=100${query ? '&sysparm_query=' + query : ''}`;
 return this.makeRequest(url);
 }

 async createDrillingOperation(data) {
 return this.makeRequest(`/api/now/table/x_1842888_drilling_drilling_operation`, {
 method: 'POST',
 body: JSON.stringify(data)
 });
 }

 async updateDrillingOperation(sysId, data) {
 return this.makeRequest(`/api/now/table/x_1842888_drilling_drilling_operation/${sysId}`, {
 method: 'PATCH',
 body: JSON.stringify(data)
 });
 }

 async getDrillingParameters(query = '') {
 const url = `/api/now/table/x_1842888_drilling_drilling_parameter?sysparm_display_value=all&sysparm_limit=100${query ? '&sysparm_query=' + query : ''}`;
 return this.makeRequest(url);
 }

 async createDrillingParameter(data) {
 return this.makeRequest(`/api/now/table/x_1842888_drilling_drilling_parameter`, {
 method: 'POST',
 body: JSON.stringify(data)
 });
 }

 async getGeologicalData(query = '') {
 const url = `/api/now/table/x_1842888_drilling_geological_data?sysparm_display_value=all&sysparm_limit=100${query ? '&sysparm_query=' + query : ''}`;
 return this.makeRequest(url);
 }

 async createGeologicalData(data) {
 return this.makeRequest(`/api/now/table/x_1842888_drilling_geological_data`, {
 method: 'POST',
 body: JSON.stringify(data)
 });
 }

 async updateGeologicalData(sysId, data) {
 return this.makeRequest(`/api/now/table/x_1842888_drilling_geological_data/${sysId}`, {
 method: 'PATCH',
 body: JSON.stringify(data)
 });
 }

 async getDrillString(query = '') {
 const url = `/api/now/table/x_1842888_drilling_drill_string?sysparm_display_value=all&sysparm_limit=100${query ? '&sysparm_query=' + query : ''}`;
 return this.makeRequest(url);
 }

 async getSafetyCompliance(query = '') {
 const url = `/api/now/table/x_1842888_drilling_safety_compliance?sysparm_display_value=all&sysparm_limit=100${query ? '&sysparm_query=' + query : ''}`;
 return this.makeRequest(url);
 }

 async getCementingOperations(query = '') {
 const url = `/api/now/table/x_1842888_drilling_cementing_operation?sysparm_display_value=all&sysparm_limit=100${query ? '&sysparm_query=' + query : ''}`;
 return this.makeRequest(url);
 }
}

const dataService = new DataService();
export default dataService;","import React, { useState, useEffect } from 'react';
import DataService from '../services/DataService.js';
import WellService from '../services/WellService.js';

export default function DrillingOperations() {
 const [operations, setOperations] = useState([]);
 const [wells, setWells] = useState([]);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState(null);
 const [selectedWell, setSelectedWell] = useState('');
 const [showForm, setShowForm] = useState(false);
 const [editingOperation, setEditingOperation] = useState(null);

 useEffect(() => {
 loadData();
 }, [selectedWell]);

 const loadData = async () => {
 try {
 setLoading(true);
 setError(null);

 const [wellsResponse, operationsResponse] = await Promise.all([
 WellService.getWells(),
 DataService.getDrillingOperations(selectedWell ? `well=${selectedWell}^ORDERBYDESCsys_created_on` : '^ORDERBYDESCsys_created_on')
 ]);

 setWells(wellsResponse.data.result || []);
 setOperations(operationsResponse.data.result || []);
 } catch (err) {
 setError(err.message);
 } finally {
 setLoading(false);
 }
 };

 const handleCreateOperation = () => {
 setEditingOperation(null);
 setShowForm(true);
 };

 const handleEditOperation = (operation) => {
 setEditingOperation(operation);
 setShowForm(true);
 };

 const handleCloseForm = () => {
 setShowForm(false);
 setEditingOperation(null);
 };

 const getStatusBadge = (status) => {
 const statusColors = {
 planned: 'badge-secondary',
 in_progress: 'badge-warning',
 completed: 'badge-success',
 suspended: 'badge-warning',
 cancelled: 'badge-danger'
 };

 const statusValue = typeof status === 'object' ? status.value : status;
 const statusLabel = typeof status === 'object' ? status.display_value : status;

 return (
 <span className={`badge ${statusColors[statusValue] || 'badge-secondary'}`}>
 {statusLabel || statusValue}
 </span>
 );
 };

 const formatDate = (date) => {
 if (!date) return '-';
 const dateValue = typeof date === 'object' ? date.display_value : date;
 return new Date(dateValue).toLocaleDateString();
 };

 const extractValue = (field) => {
 return typeof field === 'object' ? field.display_value || field.value : field;
 };

 if (loading) {
 return (
 <div className="card">
 <div style={{ textAlign: 'center', padding: '2rem' }}>
 <div>Loading drilling operations...</div>
 </div>
 </div>
 );
 }

 if (error) {
 return (
 <div className="card">
 <div style={{ color: '#ef4444', textAlign: 'center', padding: '2rem' }}>
 Error: {error}
 <br />
 <button className="btn btn-primary" onClick={loadData} style={{ marginTop: '1rem' }}>
 Retry
 </button>
 </div>
 </div>
 );
 }

 return (
 <div>
 <div className="card">
 <div className="card-header">
 <h2 className="card-title">Drilling Operations</h2>
 <div style={{ display: 'flex', gap: '1rem', alignItems: 'center' }}>
 <div>
 <select 
 value={selectedWell} 
 onChange={(e) => setSelectedWell(e.target.value)}
 className="form-select"
 >
 <option value="">All Wells</option>
 {wells.map(well => (
 <option key={extractValue(well.sys_id)} value={extractValue(well.sys_id)}>
 {extractValue(well.well_name)}
 </option>
 ))}
 </select>
 </div>
 <button className="btn btn-primary" onClick={handleCreateOperation}>
 + Add Operation
 </button>
 </div>
 </div>

 {operations.length === 0 ? (
 <div style={{ textAlign: 'center', padding: '2rem', color: '#6b7280' }}>
 No drilling operations found. Create your first operation to get started.
 </div>
 ) : (
 <div style={{ overflowX: 'auto' }}>
 <table className="table">
 <thead>
 <tr>
 <th>Operation Name</th>
 <th>Well</th>
 <th>Type</th>
 <th>Status</th>
 <th>Start Date</th>
 <th>End Date</th>
 <th>Depth Range</th>
 <th>Supervisor</th>
 <th>Actions</th>
 </tr>
 </thead>
 <tbody>
 {operations.map(operation => {
 const sysId = extractValue(operation.sys_id);
 const operationName = extractValue(operation.operation_name);
 const wellName = extractValue(operation.well);
 const operationType = extractValue(operation.operation_type);
 const supervisor = extractValue(operation.drilling_supervisor);
 const startDepth = extractValue(operation.start_depth);
 const endDepth = extractValue(operation.end_depth);

 return (
 <tr key={sysId}>
 <td><strong>{operationName}</strong></td>
 <td>{wellName}</td>
 <td>
 <span className="badge badge-info">
 {operationType?.replace('_', ' ').toUpperCase()}
 </span>
 </td>
 <td>{getStatusBadge(operation.operation_status)}</td>
 <td>{formatDate(operation.start_time)}</td>
 <td>{formatDate(operation.end_time)}</td>
 <td>
 {startDepth && endDepth ? 
 `${Number(startDepth).toLocaleString()}' - ${Number(endDepth).toLocaleString()}'` : 
 '-'
 }
 </td>
 <td>{supervisor}</td>
 <td>
 <button 
 className="btn btn-sm btn-secondary"
 onClick={() => handleEditOperation(operation)}
 >
 Edit
 </button>
 </td>
 </tr>
 );
 })}
 </tbody>
 </table>
 </div>
 )}
 </div>

 {showForm && (
 <OperationForm 
 operation={editingOperation}
 wells={wells}
 onSave={loadData}
 onClose={handleCloseForm}
 />
 )}
 </div>
 );
}

