 if (!value || !thresholds[parameter]) return 'normal';

 const numValue = parseFloat(value);
 const { min, max } = thresholds[parameter];

 if (numValue < min || numValue > max) return 'alert';
 if (numValue < min * 1.1 || numValue > max * 0.9) return 'warning';
 return 'normal';
 };

 const parameterThresholds = {
 wob: { min: 10000, max: 50000 }, // Weight on Bit (lbs)
 rop: { min: 10, max: 200 }, // Rate of Penetration (ft/hr)
 rpm: { min: 60, max: 200 }, // RPM
 torque: { min: 2000, max: 15000 }, // Torque (ft-lbs)
 mud_flow_rate: { min: 300, max: 600 }, // Flow Rate (gpm)
 standpipe_pressure: { min: 1000, max: 4000 }, // Standpipe Pressure (psi)
 gas_reading: { min: 0, max: 10 }, // Gas Reading (units)
 temperature: { min: 80, max: 300 } // Temperature (°F)
 };

 const getStatusColor = (status) => {
