import DataService from '../services/DataService.js';
import WellService from '../services/WellService.js';

export default function GeologicalData() {
 const [geologicalData, setGeologicalData] = useState([]);
 const [wells, setWells] = useState([]);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState(null);
 const [selectedWell, setSelectedWell] = useState('');
 const [showForm, setShowForm] = useState(false);
 const [editingData, setEditingData] = useState(null);

 useEffect(() => {
 loadData();
 }, [selectedWell]);

 const loadData = async () => {
 try {
 setLoading(true);
 setError(null);

 const [wellsResponse, geoResponse] = await Promise.all([
 WellService.getWells(),
 DataService.getGeologicalData(selectedWell ? `well=${selectedWell}^ORDERBYdepth_from` : '^ORDERBYdepth_from')
 ]);

 setWells(wellsResponse.data.result || []);
 setGeologicalData(geoResponse.data.result || []);
 } catch (err) {
 setError(err.message);
 } finally {
 setLoading(false);
 }
 };

 const handleCreateData = () => {
 setEditingData(null);
 setShowForm(true);
 };

 const handleEditData = (data) => {
 setEditingData(data);
 setShowForm(true);
 };

 const handleCloseForm = () => {
 setShowForm(false);
 setEditingData(null);
 };

 const extractValue = (field) => {
 return typeof field === 'object' ? field.display_value || field.value : field;
 };

 const getLithologyColor = (lithology) => {
 const colors = {
 'sandstone': '#f4a460',
 'limestone': '#d3d3d3', 
 'shale': '#2f4f4f',
 'dolomite': '#dda0dd',
 'coal': '#000000',
 'salt': '#ffffff',
 'granite': '#c0c0c0',
 'basalt': '#36454f',
 'quartzite': '#ffb6c1',
 'conglomerate': '#8b4513',
 'siltstone': '#a0522d',
 'mudstone': '#696969',
 'anhydrite': '#f5f5dc',
 'gypsum': '#fffafa',
 'schist': '#708090',
 'gneiss': '#778899',
 'slate': '#2e2e2e',
 'marble': '#f8f8ff',
 'chalk': '#f5f5f5',
 'marl': '#deb887'
 };
 return colors[lithology?.toLowerCase()] || '#cccccc';
 };

 const getReservoirQualityBadge = (quality) => {
 const qualityColors = {
 excellent: 'badge-success',
 good: 'badge-info', 
 fair: 'badge-warning',
 poor: 'badge-secondary',
 non_reservoir: 'badge-danger'
 };

 const qualityValue = typeof quality === 'object' ? quality.value : quality;
 const qualityLabel = typeof quality === 'object' ? quality.display_value : quality;

 return (
 <span className={`badge ${qualityColors[qualityValue] || 'badge-secondary'}`}>
 {qualityLabel || qualityValue}
 </span>
 );
 };

 if (loading) {
 return (
 <div className="card">
 <div style={{ textAlign: 'center', padding: '2rem' }}>
 <div>Loading geological data...</div>
 </div>
 </div>
 );
 }

 if (error) {
 return (
 <div className="card">
 <div style={{ color: '#ef4444', textAlign: 'center', padding: '2rem' }}>
 Error: {error}
 <br />
 <button className="btn btn-primary" onClick={loadData} style={{ marginTop: '1rem' }}>
 Retry
 </button>
 </div>
 </div>
 );
 }

 return (
 <div>
 <div className="card">
 <div className="card-header">
 <h2 className="card-title">Geological Data</h2>
 <div style={{ display: 'flex', gap: '1rem', alignItems: 'center' }}>
 <div>
 <select 
 value={selectedWell} 
 onChange={(e) => setSelectedWell(e.target.value)}
 className="form-select"
 >
 <option value="">All Wells</option>
 {wells.map(well => (
 <option key={extractValue(well.sys_id)} value={extractValue(well.sys_id)}>
 {extractValue(well.well_name)}
 </option>
 ))}
 </select>
 </div>
 <button className="btn btn-primary" onClick={handleCreateData}>
 + Add Geological Data
 </button>
 </div>
 </div>

 {geologicalData.length === 0 ? (
 <div style={{ textAlign: 'center', padding: '2rem', color: '#6b7280' }}>
 No geological data found. Add formation data to get started.
 </div>
 ) : (
 <div style={{ overflowX: 'auto' }}>
 <table className="table">
 <thead>
 <tr>
 <th>Well</th>
 <th>Formation</th>
 <th>Lithology</th>
 <th>Depth Range (ft)</th>
 <th>Thickness (ft)</th>
 <th>Porosity (%)</th>
 <th>Permeability (mD)</th>
 <th>Fluid Type</th>
 <th>Reservoir Quality</th>
 <th>HC Shows</th>
 <th>Actions</th>
 </tr>
 </thead>
 <tbody>
 {geologicalData.map(data => {
 const sysId = extractValue(data.sys_id);
 const wellName = extractValue(data.well);
 const formationName = extractValue(data.formation_name);
 const lithology = extractValue(data.lithology);
 const depthFrom = extractValue(data.depth_from);
 const depthTo = extractValue(data.depth_to);
 const porosity = extractValue(data.porosity);
 const permeability = extractValue(data.permeability);
 const fluidType = extractValue(data.fluid_type);
 const hcShows = extractValue(data.hydrocarbon_shows);

 const thickness = depthFrom && depthTo ? depthTo - depthFrom : null;

 return (
 <tr key={sysId}>
 <td>{wellName}</td>
 <td><strong>{formationName}</strong></td>
 <td>
 <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
 <div 
 style={{
 width: '20px',
 height: '20px',
 backgroundColor: getLithologyColor(lithology),
 border: '1px solid #ccc',
 borderRadius: '2px'
 }}
 />
 <span>{lithology}</span>
 </div>
 </td>
 <td>
 {depthFrom && depthTo ? 
 `${Number(depthFrom).toLocaleString()} - ${Number(depthTo).toLocaleString()}` : 
 '-'
 }
 </td>
 <td>{thickness ? Number(thickness).toLocaleString() : '-'}</td>
 <td>{porosity ? `${Number(porosity).toFixed(1)}%` : '-'}</td>
 <td>{permeability ? Number(permeability).toFixed(3) : '-'}</td>
 <td>
 <span className={`badge ${fluidType === 'oil' ? 'badge-success' : 
 fluidType === 'gas' ? 'badge-info' : 
 fluidType === 'water' ? 'badge-secondary' : 
 'badge-warning'}`}>
 {fluidType?.replace('_', ' ') || 'Unknown'}
 </span>
 </td>
 <td>{getReservoirQualityBadge(data.reservoir_quality)}</td>
 <td>
 {hcShows === 'true' || hcShows === true ? (
 <span className="badge badge-success">Yes</span>
 ) : (
 <span className="badge badge-secondary">No</span>
 )}
 </td>
 <td>
 <button 
 className="btn btn-sm btn-secondary"
 onClick={() => handleEditData(data)}
 >
 Edit
 </button>
 </td>
 </tr>
 );
 })}
 </tbody>
 </table>
 </div>
 )}
 </div>

 {showForm && (
 <GeologicalDataForm 
 data={editingData}
 wells={wells}
 onSave={loadData}
 onClose={handleCloseForm}
 />
 )}
 </div>
 );
}

