class ApiService {
 constructor(tableName) {
 this.tableName = tableName;
 this.baseUrl = `/api/now/table/${tableName}`;
 }

 async makeRequest(url, options = {}) {
 const defaultOptions = {
 headers: {
 'Accept': 'application/json',
 'Content-Type': 'application/json',
 'X-UserToken': window.g_ck || ''
 }
 };

 const config = {
 ...defaultOptions,
 ...options,
 headers: {
 ...defaultOptions.headers,
 ...(options.headers || {})
 }
 };

 try {
 const response = await fetch(url, config);

 if (!response.ok) {
 throw new Error(`HTTP ${response.status}: ${response.statusText}`);
 }

 const data = await response.json();
 return data;
 } catch (error) {
 console.error(`API Error for ${url}:`, error);
 throw new Error(error.message || 'Network request failed');
 }
 }

 async list(query = '', limit = 100) {
 const params = new URLSearchParams({
 sysparm_limit: limit.toString(),
 sysparm_display_value: 'all'
 });

 if (query) {
 params.append('sysparm_query', query);
 }

 const data = await this.makeRequest(`${this.baseUrl}?${params}`);
 return data.result || [];
 }

 async get(sysId) {
 const params = new URLSearchParams({
 sysparm_display_value: 'all'
 });

 const data = await this.makeRequest(`${this.baseUrl}/${sysId}?${params}`);
 return data.result;
 }

 async create(data) {
 const response = await this.makeRequest(this.baseUrl, {
 method: 'POST',
 body: JSON.stringify(data)
 });
 return response.result;
 }

 async update(sysId, data) {
 const response = await this.makeRequest(`${this.baseUrl}/${sysId}`, {
 method: 'PATCH',
 body: JSON.stringify(data)
 });
 return response.result;
 }

 async delete(sysId) {
 await this.makeRequest(`${this.baseUrl}/${sysId}`, {
 method: 'DELETE'
 });
 return true;
 }
}

// Export service instances
