 return parseFloat(getValue(wellData?.total_depth)) || 15000;
 };

 const renderWellProfile = () => {
 if (!wellData) {
 return (
 <div className="well-profile-placeholder">
 <h3>Select a well to view profile</h3>
 <p>Choose a well from the dropdown to see the animated well schematic with formations, casing, and drilling progress.</p>
 </div>
 );
 }

 const targetDepth = getTargetDepth();
 const currentDepth = getCurrentDepth();
 const maxDepth = Math.max(targetDepth, 16000);
 const scale = 800 / maxDepth;

 const sortedGeoData = [...geologicalData].sort((a, b) => parseFloat(getValue(a.depth_from)) - parseFloat(getValue(b.depth_from)));
 const sortedCasingData = [...casingData].sort((a, b) => parseFloat(getValue(b.outer_diameter)) - parseFloat(getValue(a.outer_diameter)));

 return (
 <div className="well-profile-container">
 <div className="depth-scale">
 {Array.from({length: 17}, (_, i) => (
 <div key={i} className="depth-marker" style={{top: `${i * 50}px`}}>
 <span>{(i * 1000).toLocaleString()}'</span>
 </div>
 ))}
 </div>

 <div className="well-schematic">
 <svg width="400" height="850" className="well-svg">
 {/* Surface equipment */}
 <g className="surface-equipment">
 <rect x="180" y="0" width="40" height="30" fill="#444" />
 <text x="200" y="20" textAnchor="middle" fill="white" fontSize="10">BOP</text>
 <rect x="170" y="30" width="60" height="15" fill="#666" />
 <text x="200" y="42" textAnchor="middle" fill="white" fontSize="8">Wellhead</text>
 </g>

 {/* Render formations */}
 {sortedGeoData.map((formation, index) => {
 const depthFrom = parseFloat(getValue(formation.depth_from)) * scale;
 const depthTo = parseFloat(getValue(formation.depth_to)) * scale;
 const thickness = depthTo - depthFrom;

 return (
 <g key={getValue(formation.sys_id)} className="formation-layer">
 <rect 
 x="50" 
 y={45 + depthFrom} 
 width="300" 
 height={thickness}
 fill={getLithologyColor(getValue(formation.lithology))}
 stroke="#333"
 strokeWidth="1"
 className="formation-rect clickable"
 onClick={() => setSelectedFormation(formation)}
 title={`${getValue(formation.formation_name)} - ${getValue(formation.lithology)}`}
 />

 <text 
 x="360" 
 y={45 + depthFrom + thickness/2} 
 fontSize="10" 
 fill="#333"
 className="formation-label clickable"
 onClick={() => setSelectedFormation(formation)}
 >
 {getValue(formation.formation_name)}
 </text>

 {getValue(formation.fluid_type) && getValue(formation.fluid_type) !== 'dry' && (
 <circle
 cx="40"
 cy={45 + depthFrom + thickness/2}
 r="5"
 fill={getFluidColor(getValue(formation.fluid_type))}
 className="fluid-indicator"
 title={`Fluid: ${getValue(formation.fluid_type)}`}
 >
 <animate 
 attributeName="r" 
 values="3;7;3" 
 dur={2/animationSpeed + "s"} 
 repeatCount="indefinite"
 />
 </circle>
 )}
 </g>
 );
 })}

 {/* Render casing strings with proper hole sizes */}
 {sortedCasingData.map((casing, index) => {
 const setDepth = parseFloat(getValue(casing.depth_to)) * scale;
 const diameter = Math.max(parseFloat(getValue(casing.outer_diameter)) * 1.5, 8);
 const centerX = 200;
 const casingX = centerX - diameter/2;

 // Hole size is typically 2-3 inches larger than casing
 const holeSize = diameter + 6;
 const holeX = centerX - holeSize/2;

 return (
 <g key={getValue(casing.sys_id)} className="casing-string">
 {/* Open hole */}
 <rect
 x={holeX}
 y="45"
 width={holeSize}
 height={setDepth}
 fill="#8B4513"
 opacity="0.3"
 className="open-hole"
 />

 {/* Casing pipe */}
 <rect
 x={casingX}
 y="45"
 width={diameter}
 height={setDepth}
 fill="none"
 stroke="#666"
 strokeWidth="3"
 className="casing-pipe"
 />

 {/* Casing shoe */}
 <rect
 x={casingX - 2}
 y={45 + setDepth - 8}
 width={diameter + 4}
 height="8"
 fill="#444"
 className="casing-shoe"
 />

 {/* Cement behind casing */}
 <rect
 x={casingX + diameter}
 y="45"
 width="8"
 height={setDepth}
 fill="#a0a0a0"
 opacity="0.7"
 className="cement"
 />

 {/* Casing label */}
 <text
 x={casingX - 25}
 y={45 + setDepth/2}
 fontSize="9"
 fill="#333"
 className="casing-label"
 >
 {getValue(casing.outer_diameter)}"
 </text>

 {/* Hole volume calculation display */}
 <text
 x={casingX + diameter + 15}
 y={45 + setDepth/2}
 fontSize="8"
 fill="#666"
 className="volume-label"
 >
 Vol: {((Math.PI * Math.pow(holeSize/2, 2) * parseFloat(getValue(casing.depth_to))) / 1029).toFixed(0)} bbls
 </text>
 </g>
 );
 })}

 {/* Open hole section */}
 {casingData.length > 0 && (
 <g className="open-hole">
 <rect
 x="190"
 y={45 + (Math.max(...casingData.map(c => parseFloat(getValue(c.depth_to)))) * scale)}
 width="20"
 height={(currentDepth - Math.max(...casingData.map(c => parseFloat(getValue(c.depth_to))))) * scale}
 fill="none"
 stroke="#8B4513"
 strokeWidth="2"
 strokeDasharray="3,3"
 className="open-hole-section"
 />
 </g>
 )}

 {/* Drill string */}
 {drillStringData.length > 0 && currentDepth > 0 && (
 <g className="drill-string">
 <line
 x1="200"
 y1="45"
 x2="200"
 y2={45 + currentDepth * scale}
 stroke="#FF6B35"
 strokeWidth="4"
 className="drill-pipe"
 />

 {/* BHA components */}
 {drillStringData.map((component, index) => {
 const componentDepth = (currentDepth - (index * 50)) * scale;
 const compType = getValue(component.component_type);
 return (
 <g key={getValue(component.sys_id)} className="bha-component">
 <rect
 x="195"
 y={45 + componentDepth - 10}
 width="10"
 height="20"
 fill={compType === 'drill_bit' ? '#FF0000' : '#FF6B35'}
 className="bha-tool"
 />
 <text
 x="210"
 y={45 + componentDepth}
 fontSize="8"
 fill="#333"
 >
 {compType.replace('_', ' ')}
 </text>
 </g>
 );
 })}

 {/* Animated drilling bit */}
 <circle
 cx="200"
 cy={45 + currentDepth * scale}
 r="8"
 fill="#FF0000"
 className="drill-bit"
 >
 <animateTransform
 attributeName="transform"
 type="rotate"
 values={`0 200 ${45 + currentDepth * scale};360 200 ${45 + currentDepth * scale}`}
 dur={1/animationSpeed + "s"}
 repeatCount="indefinite"
 />
 </circle>
 </g>
 )}

 {/* Target depth marker */}
 <line
 x1="50"
 y1={45 + targetDepth * scale}
 x2="350"
 y2={45 + targetDepth * scale}
 stroke="#FF4444"
 strokeWidth="2"
 strokeDasharray="5,5"
 className="target-depth-line"
 />

 {/* Current depth marker */}
 <line
 x1="50"
 y1={45 + currentDepth * scale}
 x2="350"
 y2={45 + currentDepth * scale}
 stroke="#00FF00"
 strokeWidth="2"
 className="current-depth-line"
 />
 </svg>
 </div>

 <div className="depth-indicators">
 <div className="depth-info">
 <span className="current-depth">Current: {currentDepth.toLocaleString()}'</span>
 <span className="target-depth">Target: {targetDepth.toLocaleString()}'</span>
 <span className="progress">Progress: {((currentDepth/targetDepth)*100).toFixed(1)}%</span>
 </div>
 </div>
 </div>
 );
 };

 if (loading && !wellData) {
 return (
 <div className="well-profile">
 <div className="loading-message">
 <h3>Loading drilling system...</h3>
 <p>Fetching wells and operational data...</p>
 </div>
 </div>
 );
 }

 if (error && wells.length === 0) {
