 <p>{error}</p>
 <button onClick={loadWells} className="btn btn-primary">
 Retry Connection
 </button>
 </div>
 </div>
 );
 }

 return (
 <div className="well-profile">
 <div className="profile-controls">
 <div className="well-selector">
 <label htmlFor="well-select">Select Well: </label>
 <select 
 id="well-select" 
 value={selectedWell} 
 onChange={handleWellChange}
 >
 <option value="">Choose a well...</option>
 {wells.map(well => {
 const wellId = getValue(well.sys_id);
 const wellName = getValue(well.well_name);
 const status = getValue(well.well_status);
 return (
 <option key={wellId} value={wellId}>
 {wellName} - {status}
 </option>
 );
 })}
 </select>
 </div>

 <div className="animation-controls">
 <label htmlFor="speed-slider">Animation Speed: </label>
 <input
 id="speed-slider"
 type="range"
 min="0.1"
 max="3"
 step="0.1"
 value={animationSpeed}
 onChange={(e) => setAnimationSpeed(parseFloat(e.target.value))}
 />
 <span>{animationSpeed}x</span>
 </div>

 <button 
 className="toggle-details"
 onClick={() => setShowDetails(!showDetails)}
 >
 {showDetails ? 'Hide' : 'Show'} Details
 </button>
 </div>

 <div className="profile-content">
 <div className="profile-main">
 {renderWellProfile()}
 </div>

 {showDetails && (
 <div className="profile-sidebar">
 <div className="lithology-legend">
 <h4>Formation Legend</h4>
 {[...new Set(geologicalData.map(g => getValue(g.lithology)))].map(lithology => (
 <div key={lithology} className="legend-item">
 <div 
 className="legend-color"
 style={{backgroundColor: getLithologyColor(lithology)}}
 ></div>
 <span>{lithology}</span>
 </div>
 ))}
 </div>

 {drillingParams.length > 0 && (
 <div className="drilling-status">
 <h4>Current Drilling Parameters</h4>
 <div className="param-grid">
 {[
 ['WOB', getValue(drillingParams[0].wob), 'klbs'],
 ['ROP', getValue(drillingParams[0].rop), 'ft/hr'],
 ['RPM', getValue(drillingParams[0].rpm), 'rpm'],
 ['Torque', getValue(drillingParams[0].torque), 'ft-lbs'],
 ['Flow', getValue(drillingParams[0].mud_flow_rate), 'gpm'],
 ['SPP', getValue(drillingParams[0].standpipe_pressure), 'psi']
